  'ta': r'''
{"app.name":"coscene","app.tagline":"லாஜிக், கணிதம், அல்காரிதங்கள்","ui.play":"விளையாடு","ui.continue":"தொடர்","ui.places":"தலைப்புகள்","ui.back":"பின்செல்","ui.cancel":"ரத்து","ui.done":"முடிந்தது","ui.scene_number":"காட்சி {number}","ui.place_progress":"{total}-இல் {solved} முடித்தீர்கள்","ui.locked":"பூட்டியுள்ளது","ui.locked_scene":"முதலில் இதற்கு முந்தைய காட்சியைத் தீர்த்துவிடுங்கள்.","ui.daily":"இன்றைய காட்சி","ui.daily_tagline":"தினமும் ஒரு புதிய காட்சி","ui.daily_done":"இன்று தீர்த்துவிட்டீர்கள். நாளை மீண்டும் வாருங்கள்.","ui.daily_streak":"தொடர் நாட்கள்: {days}","ui.reset_scene":"இந்தக் காட்சியை மீண்டும் தொடங்கு","ui.try_again":"சரிசெய்து மீண்டும் முயலுங்கள்.","ui.hint":"குறிப்பு","ui.hints_title":"குறிப்புகள்","ui.hint_show":"ஒரு குறிப்பைக் காட்டு","ui.hint_more":"இன்னொரு குறிப்பைக் காட்டு","ui.hint_none":"இந்தக் காட்சிக்கு அதுதான் கடைசிக் குறிப்பு.","ui.hint_cost":"குறிப்புகளைப் பயன்படுத்தினால் நட்சத்திரங்கள் குறையும்.","ui.reveal_idea":"இதன் பின்னால் இருக்கும் கருத்து","ui.reveal_seen":"இது எங்கே வருகிறது","ui.reveal_added":"உங்கள் குறிப்பேட்டில் சேர்ந்தது","ui.reveal_next":"அடுத்த காட்சி","ui.reveal_replay":"மீண்டும் விளையாடு","ui.reveal_places":"இடங்களுக்குத் திரும்பு","ui.notebook":"குறிப்பேடு","ui.notebook_empty":"நீங்கள் கண்டுபிடிக்கும் கருத்துகள் இங்கே இருக்கும்.","ui.notebook_count":"{total} கருத்துகளில் {found} கண்டுபிடித்தீர்கள்","ui.notebook_hidden":"இன்னும் கண்டுபிடிக்கவில்லை","ui.settings":"அமைப்புகள்","ui.language":"மொழி","ui.sound":"ஒலி","ui.haptics":"அதிர்வு","ui.reduce_motion":"அசைவைக் குறை","ui.left_handed":"இடது கை அமைப்பு","ui.reset_progress":"முன்னேற்றத்தை அழி","ui.reset_title":"எல்லா முன்னேற்றத்தையும் அழிக்கவா?","ui.reset_body":"உங்கள் நட்சத்திரங்கள், குறிப்புகள், குறிப்பேடு, மதிப்பெண் எல்லாம் அழிந்துவிடும். இதைத் திரும்பப் பெற முடியாது.","ui.reset_confirm":"அழி","ui.about":"செயலி பற்றி","ui.version":"பதிப்பு {version}","ui.privacy":"coscene எந்தத் தரவையும் சேகரிப்பதில்லை. இணையம் இல்லாமலும் இயங்கும்.","ui.new_scenes":"புதிய காட்சிகள் தயார்.","ui.profile":"சுயவிவரம்","ui.profile_name":"உங்கள் பெயர்","ui.profile_name_default":"ஆட்டக்காரர்","ui.profile_score_note":"cosIQ என்பது நீங்கள் தீர்க்கும் காட்சிகளை வைத்துக் கிடைக்கும் விளையாட்டு மதிப்பெண். இது அளந்து பார்த்த IQ அல்ல.","ui.profile_rank":"நிலை","ui.profile_next_rank":"{rank} நிலைக்கு இன்னும் {points} தேவை","ui.profile_top_rank":"நீங்கள் மிக உயர்ந்த நிலையில் இருக்கிறீர்கள்.","ui.profile_solved":"தீர்த்த காட்சிகள்","ui.profile_stars":"நட்சத்திரங்கள்","ui.profile_ideas":"கண்டுபிடித்த கருத்துகள்","ui.profile_streak":"தொடர் நாட்கள்","ui.profile_share":"என் அட்டையைப் பகிர்","ui.profile_share_text":"என் cosIQ {score}. உங்களால் இதை மிஞ்ச முடியுமா? #coscene","card.caption":"லாஜிக், கணிதம், அல்காரிதங்கள், கையால் தீர்த்தவை","card.scenes":"காட்சிகள்","card.stars":"நட்சத்திரங்கள்","card.ideas":"கருத்துகள்","rank.1":"துருவி","rank.2":"பயிலுநர்","rank.3":"பழுதுநீக்கி","rank.4":"பொறியாளர்","rank.5":"கண்டுபிடிப்பாளர்","rank.6":"மாமேதை","place.daily.name":"இன்றைய காட்சி","place.binary.name":"பைனரி","place.binary.tagline":"1 மற்றும் 0 மட்டும் கொண்ட எண்கள்","scene.binary.to_binary.objective":"{n} வருவதற்கான பிட்களை ஒளிரச் செய்யுங்கள்.","scene.binary.from_binary.objective":"இந்த பிட்கள் எந்த எண்ணை உருவாக்குகின்றன?","hint.binary.1":"ஒவ்வொரு பிட்டின் மதிப்பும் அதன் வலப்பக்க பிட்டைவிட இரண்டு மடங்கு.","hint.binary.2":"இன்னும் பொருந்தும் மிகப் பெரிய இட மதிப்பிலிருந்து தொடங்குங்கள், பிறகு மீதியை நிரப்புங்கள்.","hint.binary.3":"எண்ணை 8, 4, 2, 1 ஆகியவற்றின் கூட்டுத்தொகையாக எழுதுங்கள் (பெரிய எண்களுக்கு கூடுதல் இடங்கள்).","concept.binary.name":"அடிமானம் 2-இல் இட மதிப்பு","concept.binary.idea":"ஒவ்வொரு பிட்டும் இரண்டின் ஒரு அடுக்கு. பைனரியில் ஒரு எண் என்பது 1 ஆக உள்ள பிட்களின் அடுக்குகளின் கூட்டுத்தொகை.","concept.binary.seen":"நினைவகம், கோப்பு அளவு, நெட்வொர்க் மாஸ்க், கணினி சேமிக்கும் ஒவ்வொரு முழு எண்ணும்","reveal.binary":"இரண்டின் அடுக்குகளைக் கொண்டு எண்ணை உருவாக்கினீர்கள்.","place.bitwise.name":"பிட்வைஸ் ஆபரேட்டர்கள்","place.bitwise.tagline":"AND, OR, XOR மற்றும் ஷிஃப்ட்","scene.bitwise.combine.objective":"a, b இரண்டையும் பிட் பிட்டாக இணையுங்கள். எந்த எண் வருகிறது?","scene.bitwise.shift.objective":"a-வின் பிட்களை நகர்த்துங்கள். எந்த எண் வருகிறது?","hint.bitwise.1":"இரண்டு வரிசைகளையும் சேர்த்து ஒரு நேரத்தில் ஒரு நெடுவரிசையைப் பாருங்கள்.","hint.bitwise.2":"இரண்டிலும் 1 இருந்தால் மட்டுமே AND 1 வைக்கும். ஏதாவது ஒன்றில் 1 இருந்தால் OR 1 வைக்கும். இரண்டும் வேறுபட்டால் XOR 1 வைக்கும்.","hint.bitwise.3":"இடப்பக்கம் ஒரு ஷிஃப்ட் எண்ணை இரட்டிக்கும்; வலப்பக்கம் ஒரு ஷிஃப்ட் மீதியை விட்டுவிட்டு பாதியாக்கும்.","concept.bitwise.name":"பிட்வைஸ் ஆபரேட்டர்கள்","concept.bitwise.idea":"பிட்வைஸ் ஆபரேட்டர்கள் ஒவ்வொரு பிட் இடத்திலும் ஒரே நேரத்தில் வேலை செய்கின்றன, நெடுவரிசைகளுக்கு இடையே கைமாற்று இல்லை.","concept.bitwise.seen":"ஃப்ளாக்குகள் மற்றும் அனுமதிகள், இரண்டால் வேகமாகப் பெருக்கல், வகுத்தல், கிராஃபிக்ஸ், ஹேஷிங்","reveal.bitwise":"ஒவ்வொரு பிட் நெடுவரிசையாகத் தீர்த்தீர்கள்.","place.logic.name":"லாஜிக்","place.logic.tagline":"உண்மை, பொய், அவற்றுக்கு இடையிலான ஆபரேட்டர்கள்","scene.logic.evaluate.objective":"ஒவ்வொரு கூற்றும் உண்மையா (true) பொய்யா (false)?","hint.logic.1":"முதலில் ஒவ்வொரு எழுத்துக்கும் அதன் மதிப்பைப் போடுங்கள்.","hint.logic.2":"இரு பக்கமும் உண்மையாக இருந்தால் மட்டுமே && உண்மை. குறைந்தது ஒரு பக்கம் உண்மையானால் || உண்மை. ! உண்மையையும் பொய்யையும் மாற்றும்.","hint.logic.3":"முதலில் அடைப்புக்குறிக்குள், பிறகு ! குறிகள், பிறகு ||-க்கு முன் &&.","concept.logic.name":"பூலியன் லாஜிக்","concept.logic.idea":"நிரலின் ஒவ்வொரு நிபந்தனையும் இறுதியில் உண்மை அல்லது பொய், and, or, not கொண்டு இணைக்கப்படுகிறது.","concept.logic.seen":"if கூற்றுகள், தேடல் வடிகட்டிகள், தரவுத்தள WHERE நிபந்தனைகள், சர்க்யூட் வடிவமைப்பு","reveal.logic":"ஒவ்வொரு நிபந்தனையையும் படிப்படியாகச் சரிபார்த்தீர்கள்.","place.logarithms.name":"மடக்கைகள்","place.logarithms.tagline":"எத்தனை முறை பெருக்குகிறீர்கள் அல்லது பாதியாக்குகிறீர்கள்","scene.logarithms.value.objective":"மதிப்பைக் கண்டுபிடியுங்கள்.","scene.logarithms.halvings.objective":"{n}-ஐ மீண்டும் மீண்டும் பாதியாக்குகிறீர்கள், மேல்நோக்கி முழு எண்ணாக்கி. 1-ஐ அடைய எத்தனை முறை பாதியாக்க வேண்டும்?","hint.logarithms.1":"log₂ x கேட்பது: இரண்டின் எந்த அடுக்கு x தரும்?","hint.logarithms.2":"1-ஐ அடைவதற்கு முன் அடிமானத்தால் எத்தனை முறை வகுக்கலாம் என்று எண்ணுங்கள்.","hint.logarithms.3":"⌊ ⌋ கீழ்நோக்கியும் ⌈ ⌉ மேல்நோக்கியும் முழு எண்ணாக்கும். பெருக்கற்பலனின் log, log-களின் கூட்டுத்தொகை.","concept.logarithms.name":"மடக்கைகள்","concept.logarithms.idea":"மடக்கை அடிமானத்தால் எத்தனை முறை பெருக்கினீர்கள் என்று எண்ணுகிறது. n-ஐ எத்தனை முறை பாதியாக்கினால் 1 வரும் என்பதே log₂ n.","concept.logarithms.seen":"பைனரி தேடலுக்கு ஏன் சுமார் log n படிகள், வரிசைப்படுத்தல் ஏன் n log n, மரத்தின் உயரம்","reveal.logarithms":"எண்ணுக்குள் மறைந்திருந்த இரட்டிப்புகளை எண்ணினீர்கள்.","place.counting.name":"எண்ணுதல்","place.counting.tagline":"வரிசைகள், உடைகள், தேர்வுகள்","scene.counting.line_up.objective":"{n} நண்பர்கள் ஒரு வரிசையில் எத்தனை வெவ்வேறு முறைகளில் நிற்கலாம்?","scene.counting.outfits.objective":"உங்களிடம் {a} சட்டைகளும் {b} கால்சட்டைகளும் உள்ளன. எத்தனை வெவ்வேறு உடைகள் அணியலாம்?","scene.counting.podium.objective":"{n} ஓட்டக்காரர்கள் ஓடுகிறார்கள். முதல் {k} இடங்களை எத்தனை வழிகளில் நிரப்பலாம்?","scene.counting.team.objective":"{n} பேரிலிருந்து {k} பேர் கொண்ட அணியை எத்தனை வழிகளில் தேர்வு செய்யலாம்?","hint.counting.1":"ஒவ்வொரு படிக்குமான தேர்வுகளை ஒவ்வொன்றாக எண்ணுங்கள்.","hint.counting.2":"படிகள் சேர்ந்து நடந்தால் தேர்வுகளைப் பெருக்குங்கள். n! = n × (n − 1) × … × 1.","hint.counting.3":"வரிசை முக்கியம்: P(n, k) = n × (n − 1) × … k உறுப்புகள் வரை. வரிசை முக்கியமில்லை: அதை k!-ஆல் வகுங்கள்.","concept.counting.name":"வரிசைமாற்றங்கள் மற்றும் சேர்வுகள்","concept.counting.idea":"ஒவ்வொரு படியின் தேர்வுகளையும் பெருக்குங்கள். வரிசை முக்கியமில்லை என்றால், தேர்ந்தவற்றை மறுவரிசைப்படுத்தும் வழிகளால் வகுங்கள்.","concept.counting.seen":"சோதனை நிகழ்வுகளை எண்ணுதல், கடவுச்சொல் வலிமை, ப்ரூட் ஃபோர்ஸ் எவ்வளவு வேகமாக வளர்கிறது","reveal.counting":"ஒவ்வொரு படியிலும் தேர்வுகளைப் பெருக்கினீர்கள்.","place.modulo.name":"மாடுலோ","place.modulo.tagline":"மீதிகள் மற்றும் கடிகாரக் கணக்கு","scene.modulo.remainder.objective":"மீதி என்ன?","scene.modulo.clock.objective":"இப்போது மணி {h}. {k} மணி நேரம் கழித்து கடிகாரம் என்ன காட்டும்?","scene.modulo.last_digit.objective":"{b}-இன் {k} அடுக்கின் கடைசி இலக்கம் என்ன?","hint.modulo.1":"a mod m என்பது முடிந்தவரை m-ஐக் கழித்த பிறகு மீதமிருப்பது.","hint.modulo.2":"கடிகாரம் ஒவ்வொரு 12 மணி நேரத்திற்கும் சுற்றி வருகிறது, எனவே 12-ஆல் வகுத்த மீதி மட்டுமே முக்கியம்.","hint.modulo.3":"கடைசி இலக்கங்கள் ஒரு சிறிய சுழற்சியில் திரும்ப வரும். சுழற்சியின் நீளத்தைக் கண்டு, அந்த நீளத்தால் அடுக்கின் mod எடுங்கள்.","concept.modulo.name":"மாடுலர் கணிதம்","concept.modulo.idea":"மாடுலோ மீதியை மட்டும் வைத்திருக்கும், எனவே மதிப்புகள் ஒரு நிலையான வரம்பிற்குள் சுற்றி வருகின்றன.","concept.modulo.seen":"ஹேஷ் அட்டவணைகள், வட்ட பஃபர்கள், கடிகாரங்களும் நாட்காட்டிகளும், குறியாக்கவியல்","reveal.modulo":"எண்களைச் சுற்றி வர விட்டீர்கள்.","place.binary_search.name":"பைனரி தேடல்","place.binary_search.tagline":"ஒவ்வொரு முறையும் வரம்பைப் பாதியாக்குங்கள்","scene.binary_search.compare.objective":"1 முதல் {hi} வரை ஒரு எண் மறைந்துள்ளது. {budget} சோதனைகளில் அதை உறுதிசெய்யுங்கள்.","scene.binary_search.bisect.objective":"1 முதல் {hi} வரையிலான ஒரு பதிப்பு பில்டை உடைத்தது, அதற்குப் பிந்தையவை அனைத்தும் உடைந்தவை. முதல் மோசமானதை {budget} சோதனைகளில் கண்டுபிடியுங்கள்.","hint.binary_search.1":"ஒவ்வொரு பதிலும் ஒரு பக்கத்தை நீக்குகிறது. இரு பக்கங்களையும் சமமாக வையுங்கள்.","hint.binary_search.2":"எப்போதும் இன்னும் சாத்தியமானவற்றின் நடுவைச் சோதியுங்கள்.","hint.binary_search.3":"n எண்கள் மீதமிருந்தால் நடுச் சோதனை அதிகபட்சம் பாதியை விடும். அதனால் சுமார் log₂ n சோதனைகள் தேவை.","concept.binary_search.name":"பைனரி தேடல்","concept.binary_search.idea":"வரிசைப்படுத்திய வரம்பின் நடுவைச் சோதித்து, பதில் இருக்கவே முடியாத பாதியை விட்டுவிடுங்கள்.","concept.binary_search.seen":"வரிசைப்படுத்திய தரவைத் தேடுதல், git bisect, தரவுத்தள இண்டெக்ஸ்கள், பாதியாக்கி பிழை தேடுதல்","reveal.binary_search":"ஒவ்வொரு முறையும் வரம்பைப் பாதியாக்கினீர்கள்.","place.two_pointers.name":"இரு சுட்டிகள்","place.two_pointers.tagline":"இரு முனைகளிலிருந்தும் உள்ளே நடங்கள்","scene.two_pointers.pair_sum.objective":"கூட்டுத்தொகை {target} ஆகும் இரண்டு ஓடுகளைத் தேர்ந்தெடுங்கள்.","hint.two_pointers.1":"வரிசை ஒழுங்காக உள்ளது. மிகச் சிறியதும் மிகப் பெரியதும் கொண்டு தொடங்குங்கள்.","hint.two_pointers.2":"அதிகமா? வலது முனையை உள்ளே நகர்த்துங்கள். குறைவா? இடது முனையை உள்ளே நகர்த்துங்கள்.","hint.two_pointers.3":"ஒவ்வொரு படியும் ஒரு ஓட்டை நிரந்தரமாக நீக்குகிறது, எனவே எந்த ஜோடியையும் இருமுறை சோதிக்க வேண்டாம்.","concept.two_pointers.name":"இரு சுட்டிகள்","concept.two_pointers.idea":"ஒழுங்கான தரவில், ஒன்றையொன்று நோக்கி நகரும் இரு முனைகள் ஒரே பயணத்தில் ஜோடியைக் கண்டுபிடிக்கும்.","concept.two_pointers.seen":"இரு கூட்டல், ஒழுங்கான பட்டியல்களை இணைத்தல், இடத்திலேயே நகல்களை நீக்குதல்","reveal.two_pointers":"இரு முனைகளிலிருந்தும் உள்ளே நடந்தீர்கள்.","place.stacks.name":"ஸ்டாக்","place.stacks.tagline":"கடைசியாக வந்தது, முதலில் போகும்","scene.stacks.stack.objective":"பொருட்கள் வரிசையாக வருகின்றன. ஸ்டாக்கைக் கொண்டு அவற்றை இலக்கு வரிசையில் அனுப்புங்கள்.","scene.stacks.stack_cap.objective":"பொருட்கள் வரிசையாக வருகின்றன. அவற்றை இலக்கு வரிசையில் அனுப்புங்கள். ஸ்டாக்கில் அதிகபட்சம் {cap} இருக்கலாம்.","hint.stacks.1":"ஸ்டாக்கிலிருந்து மேலே உள்ளது மட்டுமே வெளியே வர முடியும்.","hint.stacks.2":"அடுத்து வேண்டியது மேலே வரும்வரை push செய்யுங்கள், பிறகு அதை pop செய்யுங்கள்.","hint.stacks.3":"வேண்டியது மற்றவற்றின் கீழ் புதைந்திருந்தால் அந்த வரிசை சாத்தியமில்லை, எனவே முன்கூட்டியே திட்டமிடுங்கள்.","concept.stacks.name":"ஸ்டாக்","concept.stacks.idea":"ஸ்டாக் மிகச் சமீபத்திய பொருளை மட்டுமே எடுக்க விடும். கடைசியாக வந்தது, முதலில் போகும்.","concept.stacks.seen":"Undo, கால் ஸ்டாக், அடைப்புக்குறிகளைச் சரிபார்த்தல், உலாவியின் பின் பொத்தான்","reveal.stacks":"கடைசியாக வந்தது முதலில் போகும், கையால் தீர்த்தீர்கள்.","place.queues.name":"வரிசை (Queue)","place.queues.tagline":"முதலில் வந்தது, முதலில் போகும்","scene.queues.front.objective":"→ பின்னால் சேர்க்கும், ← முன்னிருந்து எடுக்கும். இறுதியில் முன்னால் இருப்பது யார்?","scene.queues.front_size.objective":"→ பின்னால் சேர்க்கும், ← முன்னிருந்து எடுக்கும். முன்னால் இருப்பது யார், எத்தனை மீதம்?","scene.queues.front_last.objective":"→ பின்னால் சேர்க்கும், ← முன்னிருந்து எடுக்கும். முன்னால் இருப்பது யார், கடைசியாக வெளியேறியது யார்?","hint.queues.1":"வரிசையை எழுதி வைத்து ஒவ்வொரு படிக்குப் பிறகும் புதுப்பியுங்கள்.","hint.queues.2":"புதியவை பின்னால் சேரும். எப்போதும் முன்னிருந்துதான் வெளியேறும்.","hint.queues.3":"வரிசைக்குள் ஒழுங்கு ஒருபோதும் மாறாது. முனைகள் மட்டுமே நகரும்.","concept.queues.name":"வரிசை (Queue)","concept.queues.idea":"வரிசை பொருட்களை அவை வந்த ஒழுங்கிலேயே வழங்கும். முதலில் வந்தது, முதலில் போகும்.","concept.queues.seen":"அச்சுப் பணிகள், பணி திட்டமிடுபவர்கள், அகலம்-முதல் தேடல், செய்தி ப்ரோக்கர்கள்","reveal.queues":"முதலில் வந்தது, முதலில் போனது.","place.bit_tricks.name":"பிட் தந்திரங்கள்","place.bit_tricks.tagline":"சிறிய சூத்திரங்கள், பெரிய குறுக்குவழிகள்","scene.bit_tricks.popcount.objective":"பைனரியில் {n}-இல் எத்தனை 1 பிட்கள் உள்ளன?","scene.bit_tricks.clear_low.objective":"n & (n − 1) என்ன?","scene.bit_tricks.power_of_two.objective":"ஒவ்வொரு எண்ணும் இரண்டின் அடுக்கா?","hint.bit_tricks.1":"முதலில் எண்ணைப் பைனரியில் எழுதுங்கள்.","hint.bit_tricks.2":"n − 1 மிகக் கீழான 1 பிட்டை 0 ஆகவும் அதற்குக் கீழுள்ள ஒவ்வொரு 0-ஐயும் 1 ஆகவும் மாற்றும்.","hint.bit_tricks.3":"எனவே n & (n − 1) மிகக் கீழான 1 பிட்டை நீக்கும். இரண்டின் அடுக்கில் சரியாக ஒரு 1 பிட் இருப்பதால் விடை 0.","concept.bit_tricks.name":"பிட் கையாளுதல்","concept.bit_tricks.idea":"n & (n − 1) மிகக் கீழான 1 பிட்டை அழிக்கும். மீண்டும் செய்தால் 1 பிட்கள் எண்ணப்படும்; 0 வந்தால் இரண்டின் அடுக்கு.","concept.bit_tricks.seen":"1 பிட்களை எண்ணுதல், இரண்டின் அடுக்கைச் சோதித்தல், அனுமதி மாஸ்க்குகள், வேகமான ஹேஷ்கள்","reveal.bit_tricks":"மிகக் கீழான பிட்டைக் கொண்டு எண்ணினீர்கள்.","place.sorting.name":"வரிசைப்படுத்தல்","place.sorting.tagline":"ஒவ்வொரு இடமாற்றமும் முக்கியம்","scene.sorting.bubble.objective":"வரிசையைச் சிறியதிலிருந்து பெரியதாக அடுக்குங்கள். அருகருகே உள்ளவற்றை மட்டுமே மாற்றலாம், அதிகபட்சம் {budget} இடமாற்றங்கள்.","scene.sorting.any_swap.objective":"வரிசையைச் சிறியதிலிருந்து பெரியதாக அடுக்குங்கள். எந்த இரு ஓடுகளையும் மாற்றலாம், அதிகபட்சம் {budget} இடமாற்றங்கள்.","hint.sorting.1":"மாற்ற ஒரு ஓட்டைத் தட்டி, பிறகு இன்னொன்றைத் தட்டுங்கள்.","hint.sorting.2":"அருகருகே இடமாற்றத்தில், தவறான வரிசையில் உள்ள ஒவ்வொரு ஜோடிக்கும் ஒரு இடமாற்றம் தேவை.","hint.sorting.3":"எந்த இடமாற்றத்திலும், முதலில் மிகச் சிறிய ஓட்டை அதன் இடத்தில் வையுங்கள், பிறகு அடுத்த சிறியதை.","concept.sorting.name":"இடமாற்றங்களால் வரிசைப்படுத்தல்","concept.sorting.idea":"அருகருகே இடமாற்றங்களுக்கு தவறான ஒவ்வொரு ஜோடிக்கும் ஒன்று. தாராள இடமாற்றங்களுக்கு ஒவ்வொரு ஓட்டுக்கும் ஒன்று, ஒவ்வொரு சுழற்சிக்கும் ஒன்று குறைவு.","concept.sorting.seen":"பபிள் சார்ட் மற்றும் செலக்ஷன் சார்ட், தலைகீழ் ஜோடிகளை எண்ணுதல், தரவு எவ்வளவு கலைந்துள்ளது என்று அளத்தல்","reveal.sorting":"அடுக்கப்பட்டது, ஒரு இடமாற்றமும் கூடுதலாக இல்லாமல்.","place.hashing.name":"ஹேஷிங்","place.hashing.tagline":"தேடாமலேயே வாளியைக் கண்டுபிடியுங்கள்","scene.hashing.bucket.objective":"ஒவ்வொரு விசையும் (key) எந்த வாளிக்குச் செல்கிறது?","scene.hashing.collisions.objective":"விசைகள் ஒவ்வொன்றாகச் சேர்க்கப்படுகின்றன. ஏற்கெனவே நிரம்பிய வாளியில் எத்தனை விழுகின்றன?","scene.hashing.probing.objective":"விசைகள் ஒவ்வொன்றாகச் சேர்க்கப்படுகின்றன. நிரம்பிய வாளி விசையை அடுத்த காலி வாளிக்கு அனுப்பும். {last} எந்த வாளியில் சேர்கிறது?","hint.hashing.1":"h(k) = k mod m: m-ஆல் வகுத்து மீதியை வையுங்கள்.","hint.hashing.2":"விசைகளை வரிசையாக எடுத்து எந்த வாளிகள் நிரம்பியுள்ளன என்று கவனியுங்கள்.","hint.hashing.3":"லீனியர் ப்ரோபிங் அடுத்த வாளியை முயலும், கடைசியிலிருந்து 0-க்குச் சுற்றி வரும்.","concept.hashing.name":"ஹேஷ் அட்டவணைகள்","concept.hashing.idea":"ஹேஷ் விசையை நேரடியாக வாளி எண்ணாக மாற்றுவதால் தேட வேண்டியதில்லை. மோதல்களை மட்டும் கையாள வேண்டும்.","concept.hashing.seen":"டிக்ஷனரிகளும் செட்களும், தரவுத்தள இண்டெக்ஸ்கள், கேஷ்கள், சுமை சமன்படுத்திகள்","reveal.hashing":"தேடாமலேயே ஒவ்வொரு வாளியையும் கண்டீர்கள்.","place.recursion.name":"ரிகர்ஷன்","place.recursion.tagline":"தன்னையே அழைக்கும் ஃபங்ஷன்","scene.recursion.value.objective":"விதியிலிருந்து மதிப்பைக் கண்டுபிடியுங்கள்.","scene.recursion.calls.objective":"முதல் அழைப்பையும் சேர்த்து, fib({n}) மொத்தம் எத்தனை அழைப்புகள் செய்கிறது?","hint.recursion.1":"மிகச் சிறிய நிகழ்விலிருந்து தொடங்கி மேலே கட்டுங்கள்.","hint.recursion.2":"மதிப்புகளை வரிசையாக எழுதுங்கள்: f(0), f(1), f(2)… ஒவ்வொன்றும் முந்தையவற்றைப் பயன்படுத்துகிறது.","hint.recursion.3":"அழைப்புகளுக்கு, ஒவ்வொரு அழைப்பும் 1 மற்றும் அதன் இரு குழந்தைகளின் அழைப்புகளைச் சேர்க்கும்.","concept.recursion.name":"ரிகர்ஷன்","concept.recursion.idea":"ரிகர்சிவ் விதி ஒரு மதிப்பை தன்னுடைய சிறிய மதிப்புகளைக் கொண்டு வரையறுக்கிறது, அடிப்படை நிகழ்வு வரை.","concept.recursion.seen":"மரப் பயணம், பிரித்து வெல்லுதல், பார்சிங், சாதாரண ரிகர்சிவ் fib ஏன் மெதுவாக உள்ளது","reveal.recursion":"அடிப்படை நிகழ்விலிருந்து மேலே கட்டினீர்கள்.","place.sliding_window.name":"நகரும் சாளரம்","place.sliding_window.tagline":"நகர்த்துங்கள், ஒன்று சேர், ஒன்று விடு","scene.sliding_window.window.objective":"மிகப் பெரிய கூட்டுத்தொகை கொண்ட {k} அடுத்தடுத்த ஓடுகளைத் தேர்ந்தெடுங்கள்.","hint.sliding_window.1":"ஒவ்வொரு சாளரத்திலும் சரியாக {k} அடுத்தடுத்த ஓடுகள் இருக்கும்.","hint.sliding_window.2":"சாளரத்தை ஒரு படி நகர்த்தினால் ஒரு ஓடு சேரும், ஒன்று விடுபடும்.","hint.sliding_window.3":"நகர்த்தும்போது நடப்புக் கூட்டுத்தொகையையும் இதுவரையிலான சிறந்ததையும் நினைவில் வையுங்கள்.","concept.sliding_window.name":"நகரும் சாளரம்","concept.sliding_window.idea":"நிலையான அளவுள்ள சாளரத்தை தரவின் மேல் நகர்த்தி, ஒன்று உள்ளே ஒன்று வெளியே என்று கூட்டுத்தொகையைப் புதுப்பியுங்கள்.","concept.sliding_window.seen":"நகரும் சராசரிகள், வீத வரம்புகள், நீண்ட துணைச்சரம் கேள்விகள், ஸ்ட்ரீமிங் தரவு","reveal.sliding_window":"மீண்டும் தொடங்காமல் சாளரத்தை நகர்த்தினீர்கள்.","place.prefix_sums.name":"முன்னொட்டுக் கூட்டல்","place.prefix_sums.tagline":"எந்த வரம்பின் கூட்டலும் ஒரே படியில்","scene.prefix_sums.range.objective":"இந்த வரம்பின் கூட்டுத்தொகை என்ன?","scene.prefix_sums.from_prefix.objective":"P-இல் நடப்புக் கூட்டல்கள் உள்ளன: P[i] = a[0] + … + a[i]. வரம்பின் கூட்டுத்தொகை என்ன?","hint.prefix_sums.1":"முதல் இண்டெக்ஸிலிருந்து கடைசி வரை, இரண்டையும் சேர்த்து, மதிப்புகளைக் கூட்டுங்கள்.","hint.prefix_sums.2":"P[j] என்பது j வரையிலான மொத்தம். i-க்கு முன் உள்ள அனைத்தையும் கழியுங்கள்.","hint.prefix_sums.3":"a[i] … a[j]-இன் கூட்டுத்தொகை P[j] − P[i − 1].","concept.prefix_sums.name":"முன்னொட்டுக் கூட்டல்","concept.prefix_sums.idea":"நடப்புக் கூட்டல்களை ஒருமுறை சேமித்தால், எந்த வரம்பின் கூட்டலும் ஒரு கழித்தல்தான்.","concept.prefix_sums.seen":"வரம்பு வினவல்கள், 2D படக் கூட்டல்கள், பகுப்பாய்வு டாஷ்போர்டுகள்","reveal.prefix_sums":"ஒரு கழித்தலே வரம்புக்குப் பதில் சொன்னது.","place.greedy.name":"பேராசைத் தேர்வுகள்","place.greedy.tagline":"ஒவ்வொரு படியிலும் சிறந்த தேர்வு","scene.greedy.meetings.objective":"ஒரே அறையில் முடிந்தவரை அதிக கூட்டங்களை முன்பதிவு செய்யுங்கள். எந்த இரண்டும் மேற்பொருந்தக் கூடாது.","hint.greedy.1":"சீக்கிரம் முடியும் கூட்டம் மற்றவற்றுக்கு அதிக இடம் விடும்.","hint.greedy.2":"முடியும் நேரப்படி அடுக்குங்கள். முதலாவதை எடுத்து, அது முடிந்த பின் தொடங்கும் அடுத்ததை எடுங்கள்.","hint.greedy.3":"தொட்டுக்கொள்ளும் கூட்டங்கள், ஒன்று 5-இல் முடிந்து அடுத்தது 5-இல் தொடங்கினால், மேற்பொருந்தாது.","concept.greedy.name":"பேராசை அல்காரிதங்கள்","concept.greedy.idea":"மீண்டும் மீண்டும் முதலில் முடியும் கூட்டத்தைத் தேர்ந்தால் அதிக கூட்டங்கள் கிடைக்கும்.","concept.greedy.seen":"இடைவெளி திட்டமிடல், எளிய நாணயங்களில் சில்லறை, ஹஃப்மன் குறியீடுகள்","reveal.greedy":"ஒவ்வொரு முறையும் முதலில் முடிவதே வென்றது.","place.heaps.name":"ஹீப்","place.heaps.tagline":"மிகச் சிறியது எப்போதும் மேலே","scene.heaps.last_out.objective":"+ ஒரு எண்ணைச் சேர்க்கும். − மிகச் சிறியதை எடுக்கும். கடைசி − எந்த எண்ணை எடுக்கிறது?","scene.heaps.first_last.objective":"+ ஒரு எண்ணைச் சேர்க்கும். − மிகச் சிறியதை எடுக்கும். முதலிலும் கடைசியிலும் எந்த எண்கள் வெளியேறுகின்றன?","scene.heaps.top_size.objective":"+ ஒரு எண்ணைச் சேர்க்கும். − மிகச் சிறியதை எடுக்கும். இறுதியில் மேலே என்ன, எத்தனை மீதம்?","hint.heaps.1":"உள்ளே என்ன உள்ளது என்ற பட்டியலை வைத்து ஒவ்வொரு படிக்குப் பிறகும் புதுப்பியுங்கள்.","hint.heaps.2":"ஒவ்வொரு −-உம் அந்த நேரத்தில் உள்ளே உள்ள மிகச் சிறிய எண்ணை எடுக்கும்.","hint.heaps.3":"எண்கள் சேர்க்கப்பட்ட வரிசை முக்கியமில்லை, அவற்றின் அளவே முக்கியம்.","concept.heaps.name":"ஹீப்கள் மற்றும் முன்னுரிமை வரிசைகள்","concept.heaps.idea":"மின்-ஹீப் பொருட்கள் எந்த வரிசையில் வந்தாலும் எப்போதும் மிகச் சிறியதையே முதலில் தரும்.","concept.heaps.seen":"பணி திட்டமிடல், டைக்ஸ்ட்ரா அல்காரிதம், டாப்-k கேள்விகள், நிகழ்வு உருவகப்படுத்தல்கள்","reveal.heaps":"ஒவ்வொரு முறையும் மிகச் சிறியது முதலில்.","place.bfs.name":"அகலம்-முதல் தேடல்","place.bfs.tagline":"ஒவ்வொரு படியாகப் பரவுங்கள்","scene.bfs.fewest_steps.objective":"ஆரஞ்சுப் புள்ளியிலிருந்து வளையம் வரை மிகக் குறுகிய பாதையை வரையுங்கள். அடர் கட்டங்கள் சுவர்கள்.","hint.bfs.1":"1 படியில் அடையக்கூடிய ஒவ்வொரு கட்டத்தையும் யோசியுங்கள், பிறகு 2, பிறகு 3.","hint.bfs.2":"எல்லாத் திசைகளிலும் சமமாகப் பரவினால் ஒவ்வொரு கட்டமும் அதன் குறுகிய பாதையிலேயே முதலில் அடையப்படும்.","hint.bfs.3":"சுவர்கள் சுற்றுவழியைக் கட்டாயப்படுத்தும். முடிவு செய்யும் முன் சில பாதைகளின் படிகளை எண்ணுங்கள்.","concept.bfs.name":"அகலம்-முதல் தேடல்","concept.bfs.idea":"அடுக்கடுக்காக ஆராய்ந்தால் ஒவ்வொரு கட்டத்தையும் குறைந்த படிகளில் அடையலாம்.","concept.bfs.seen":"புதிர்ப் பாதைகளிலும் வரைபடங்களிலும் குறுகிய வழி, சமூக வலைப்பின்னல் தூரம், வலை கிராலர்கள்","reveal.bfs":"மிகக் குறைந்த படிகளை எடுத்தீர்கள்.","place.combinatorics.name":"சேர்வியல்","place.combinatorics.tagline":"பட்டியலிடாமல் எண்ணுதல்","scene.combinatorics.choose.objective":"சேர்வுகளின் எண்ணிக்கையைக் கண்டுபிடியுங்கள்.","scene.combinatorics.sweets.objective":"{k} ஒரே மாதிரியான இனிப்புகளை {n} குழந்தைகளுக்குப் பகிருங்கள். சிலருக்கு ஒன்றும் கிடைக்காமல் போகலாம். எத்தனை வழிகள்?","scene.combinatorics.socks.objective":"இழுப்பறையில் {c} நிறங்களில் காலுறைகள் உள்ளன. பார்க்காமல் எத்தனை எடுத்தால் ஒரே நிறத்தில் {m} உறுதி?","scene.combinatorics.divisible.objective":"1 முதல் {n} வரை எத்தனை எண்கள் {a} அல்லது {b}-ஆல் வகுபடும்?","hint.combinatorics.1":"n-இல் இருந்து k-ஐத் தேர்வு செய்ய: C(n, k) = n! ÷ (k! × (n − k)!).","hint.combinatorics.2":"இனிப்புகள்: அவற்றை வரிசையாக வைத்து குழந்தைகளுக்கு இடையே பிரிப்பான்களைப் போடுங்கள். பிரிப்பான்கள் எங்கே என்று தேர்ந்தெடுங்கள்.","hint.combinatorics.3":"புறாக்கூடு: முதலில் மோசமான அதிர்ஷ்டத்தை யோசியுங்கள். வகுபடுபவை: ஒவ்வொன்றையும் எண்ணி, இருமுறை எண்ணியவற்றைக் கழியுங்கள்.","concept.combinatorics.name":"சேர்வியல்","concept.combinatorics.idea":"புத்திசாலித்தனமான எண்ணுதல்: சேர்வுகள், நட்சத்திரங்களும் கோடுகளும், புறாக்கூடு கொள்கை, உள்ளடக்கல்–விலக்கல்.","concept.combinatorics.seen":"தேடல் வெளியை மதிப்பிடுதல், ஹேஷ் மோதல்கள், நிகழ்தகவு, புதிர் நேர்காணல்கள்","reveal.combinatorics":"ஒரு நிகழ்வையும் பட்டியலிடாமல் எண்ணினீர்கள்.","place.dynamic_programming.name":"டைனமிக் புரோகிராமிங்","place.dynamic_programming.tagline":"சிறிய நிகழ்வுகளைத் தீர்த்து மீண்டும் பயன்படுத்துங்கள்","scene.dynamic_programming.stairs.objective":"{n} படிகள் ஏறுகிறீர்கள், ஒரு முறைக்கு இத்தனை படிகளாக. மேலே செல்ல எத்தனை வெவ்வேறு வழிகள்?","scene.dynamic_programming.coins.objective":"இந்த நாணயங்களை எத்தனை முறை வேண்டுமானாலும் பயன்படுத்தி, {amount} ஆக்க குறைந்தபட்சம் எத்தனை நாணயங்கள் தேவை?","scene.dynamic_programming.grid_paths.objective":"வலது அல்லது கீழ் மட்டுமே நகருங்கள், ■-ஐத் தவிர்த்து. மேல்-இடதிலிருந்து கீழ்-வலது வரை எத்தனை பாதைகள்?","hint.dynamic_programming.1":"முதலில் சிறிய நிகழ்வுகளுக்கு விடை காணுங்கள்: 1 படி, 2 படிகள், தொகை 1, முதல் வரிசை.","hint.dynamic_programming.2":"ஒவ்வொரு விடையும் ஏற்கெனவே கிடைத்த விடைகளிலிருந்து கட்டப்படுகிறது.","hint.dynamic_programming.3":"படிகள்: கீழுள்ள படிகளின் வழிகளைக் கூட்டுங்கள். நாணயங்கள்: 1 + ஒவ்வொரு நாணயத்தையும் கழித்த தொகைக்கான சிறந்தது. கட்டம்: மேலும் இடதுமான கட்டங்களைக் கூட்டுங்கள்.","concept.dynamic_programming.name":"டைனமிக் புரோகிராமிங்","concept.dynamic_programming.idea":"சிறிய நிகழ்வுகளின் விடைகளைச் சேமித்து அவற்றிலிருந்து பெரியவற்றைக் கட்டுங்கள், எதையும் இருமுறை கணக்கிட வேண்டாம்.","concept.dynamic_programming.seen":"எடிட் தூரம், வழித் திட்டமிடல், நாணயச் சில்லறை, பல நேர்காணல் கேள்விகள்","reveal.dynamic_programming":"சிறிய விடைகளை மீண்டும் பயன்படுத்தி பெரியதைக் கட்டினீர்கள்.","place.knapsack.name":"நாப்சாக்","place.knapsack.tagline":"வரம்புக்குள் சிறந்த மதிப்பு","scene.knapsack.bag.objective":"பையை {cap} kg வரை நிரப்புங்கள், மொத்த மதிப்பு மிக அதிகமாக இருக்கட்டும்.","hint.knapsack.1":"மிக மதிப்பான பொருட்கள் எப்போதும் சிறந்த தேர்வல்ல.","hint.knapsack.2":"ஒரு கிலோவுக்கான மதிப்பைப் பாருங்கள், ஆனால் மீதமுள்ள இடம் வீணாகவில்லையா என்று சோதியுங்கள்.","hint.knapsack.3":"ஒரு பொருளுக்குப் பதிலாக இரண்டு இலேசானவற்றை வைத்து மொத்தங்களை ஒப்பிடுங்கள்.","concept.knapsack.name":"0/1 நாப்சாக்","concept.knapsack.idea":"எடை வரம்புக்குள் பொருட்களைத் தேர்வதற்கு ஒவ்வொரு கலவையையும் எடைபோட வேண்டும். பேராசைத் தேர்வுகள் சிறந்ததைத் தவறவிடலாம்.","concept.knapsack.seen":"பட்ஜெட் திட்டமிடல், வள ஒதுக்கீடு, சரக்கு ஏற்றுதல், விளம்பரத் தேர்வு","reveal.knapsack":"பொருந்தியவற்றில் சிறந்த மதிப்பு.","place.shortest_paths.name":"குறுகிய பாதைகள்","place.shortest_paths.tagline":"மலிவானது, குறுகியது அல்ல","scene.shortest_paths.cheapest.objective":"ஆரஞ்சுப் புள்ளியிலிருந்து வளையம் வரை மிக மலிவான பாதையை வரையுங்கள். ஒவ்வொரு கட்டத்திலும் நுழைய அதன் எண்ணே செலவு.","hint.shortest_paths.1":"குறைந்த படிகள் கொண்ட பாதை எப்போதும் மலிவானதல்ல.","hint.shortest_paths.2":"சுற்றுவழி குறைவாகச் செலவானால் விலையுயர்ந்த கட்டங்களைச் சுற்றிச் செல்லுங்கள்.","hint.shortest_paths.3":"டைக்ஸ்ட்ரா அல்காரிதம் எப்போதும் இதுவரை கண்ட மலிவான பாதையையே நீட்டிக்கும்.","concept.shortest_paths.name":"டைக்ஸ்ட்ரா அல்காரிதம்","concept.shortest_paths.idea":"எப்போதும் அடுத்து தெரிந்த மலிவான பாதையை நீட்டியுங்கள். எதிர்மறைச் செலவுகள் இல்லாவிட்டால் இது மலிவான வழியைத் தரும்.","concept.shortest_paths.seen":"வரைபடங்களும் வழிகாட்டலும், நெட்வொர்க் ரூட்டிங், விளையாட்டு AI","reveal.shortest_paths":"மலிவானது, குறுகியது அல்ல.","place.topological_sort.name":"இடவியல் வரிசை","place.topological_sort.tagline":"சார்ந்தவை முதலில்","scene.topological_sort.tasks.objective":"வேலை செய்யும் வரிசையில் பணிகளைத் தட்டுங்கள். அம்புக்குறி என்றால் முதல் பணி இரண்டாவதற்கு முன் வர வேண்டும்.","hint.topological_sort.1":"எந்த அம்புக்குறியும் சுட்டாத பணியிலிருந்து தொடங்குங்கள்.","hint.topological_sort.2":"ஒரு பணியைச் செய்த பின் அதன் அம்புக்குறிகள் கணக்கில் இல்லை.","hint.topological_sort.3":"மீண்டும் செய்யுங்கள்: இனி எந்த அம்புக்குறியும் சுட்டாத எந்தப் பணியையும் தேர்ந்தெடுங்கள்.","concept.topological_sort.name":"இடவியல் வரிசை","concept.topological_sort.idea":"ஒவ்வொரு பணியும் அது சார்ந்த பணிகளுக்குப் பிறகு வரும்படி பணிகளை வரிசைப்படுத்துதல்.","concept.topological_sort.seen":"பில்ட் அமைப்புகள், தொகுப்பு மேலாளர்கள், பாடத் திட்டமிடல், விரிதாள் புதுப்பிப்புகள்","reveal.topological_sort":"ஒவ்வொரு பணியும் தனக்குத் தேவையானவற்றுக்குப் பின் வந்தது.","place.search_the_answer.name":"விடையில் தேடல்","place.search_the_answer.tagline":"முடிவின் மீது பைனரி தேடல்","scene.search_the_answer.ship.objective":"இந்தப் பொட்டலங்களை இதே வரிசையில் {days} நாட்களில் அனுப்புங்கள். வேலை செய்யும் மிகச் சிறிய தினசரி வரம்பு எது?","scene.search_the_answer.isqrt.objective":"வர்க்கம் {n}-ஐ மிஞ்சாத மிகப் பெரிய முழு எண் எது?","hint.search_the_answer.1":"ஒரு விடையை ஊகித்து அது வேலை செய்கிறதா என்று சோதியுங்கள்.","hint.search_the_answer.2":"ஒரு வரம்பு வேலை செய்தால் அதைவிடப் பெரிய ஒவ்வொன்றும் வேலை செய்யும், எனவே விடையின் மீது பைனரி தேடல் செய்யுங்கள்.","hint.search_the_answer.3":"விடை குறைந்தபட்சம் கனமான பொட்டலம் அளவும் அதிகபட்சம் மொத்த எடை அளவும் இருக்கும்.","concept.search_the_answer.name":"விடையின் மீது பைனரி தேடல்","concept.search_the_answer.idea":"ஒரு விடை வேலை செய்த பின் பெரிய விடைகளும் வேலை செய்தால், விடையின் மீதே பைனரி தேடல் செய்யலாம்.","concept.search_the_answer.seen":"திறன் திட்டமிடல், வர்க்கமூலங்கள், வேலையைச் சமமாகப் பிரித்தல், பல நேர்காணல் கேள்விகள்","reveal.search_the_answer":"தரவை அல்ல, விடையைத் தேடினீர்கள்.","place.xor_tricks.name":"XOR தந்திரங்கள்","place.xor_tricks.tagline":"ஒன்றையொன்று ரத்து செய்பவை","scene.xor_tricks.subset.objective":"XOR {target} ஆகும் ஓடுகளைத் தேர்ந்தெடுங்கள்.","scene.xor_tricks.single.objective":"ஒன்றைத் தவிர ஒவ்வொரு எண்ணும் இருமுறை வருகிறது. தனியாக இருப்பது எது?","scene.xor_tricks.swap.objective":"மூன்று வரிகளையும் இயக்குங்கள். இறுதியில் a, b என்ன?","hint.xor_tricks.1":"x ^ x = 0, x ^ 0 = x.","hint.xor_tricks.2":"XOR பிட்களைப் பற்றியது: தேர்ந்த ஓடுகளில் ஒற்றைப்படை எண்ணிக்கையில் 1 இருந்தால் அந்த நெடுவரிசை 1.","hint.xor_tricks.3":"ஜோடிகள் ஒன்றையொன்று ரத்து செய்வதால், எல்லாவற்றின் XOR தனி எண்ணை மட்டும் விடும்.","concept.xor_tricks.name":"XOR","concept.xor_tricks.idea":"XOR ஜோடிகளை ரத்து செய்யும்: x ^ x = 0. இதனால் தனிப் பொருள் கிடைக்கும், மதிப்புகள் மாறும், சமநிலை சோதிக்கப்படும்.","concept.xor_tricks.seen":"தனி எண்ணைக் கண்டுபிடித்தல், RAID சமநிலை, சரிபார்ப்புத் தொகைகள், எளிய குறியாக்கம்","reveal.xor_tricks":"ஜோடிகள் ரத்தாகின.","place.union_find.name":"யூனியன்–ஃபைண்ட்","place.union_find.tagline":"யார் யாருடன் இணைந்துள்ளார்","scene.union_find.groups.objective":"1 முதல் {n} வரை நபர்கள். ஒவ்வொரு இணைப்பும் இருவரை ஒரே குழுவில் சேர்க்கிறது. எத்தனை குழுக்கள்?","scene.union_find.groups_biggest.objective":"1 முதல் {n} வரை நபர்கள். ஒவ்வொரு இணைப்பும் இரு குழுக்களை இணைக்கிறது. எத்தனை குழுக்கள், பெரியது எவ்வளவு பெரியது?","hint.union_find.1":"தொடக்கத்தில் ஒவ்வொருவரும் தனிக் குழுவில்.","hint.union_find.2":"ஒவ்வொரு இணைப்பும் இரு குழுக்களை இணைக்கும், அவை ஏற்கெனவே ஒரே குழுவாக இல்லாவிட்டால்.","hint.union_find.3":"இணைப்பு இல்லாதவர்கள் ஒருவர் கொண்ட குழுக்கள்.","concept.union_find.name":"யூனியன்–ஃபைண்ட்","concept.union_find.idea":"முழுப் படத்தையும் மீண்டும் வரையாமல், இணைப்புகள் வரும்போதே குழுக்களை இணைத்துக் கண்காணியுங்கள்.","concept.union_find.seen":"நெட்வொர்க் இணைப்பு, க்ருஸ்கல் விரிவு மரங்கள், நண்பர் வட்டங்கள், படப் பகுதிகள்","reveal.union_find":"இணைப்புகள் வரும்போதே குழுக்களை இணைத்தீர்கள்.","place.probability.name":"நிகழ்தகவு","place.probability.tagline":"விளைவுகளை எண்ணுங்கள்","scene.probability.dice_sum.objective":"இரண்டு பகடைகளை உருட்டுகிறீர்கள். 36 விளைவுகளில் எத்தனையில் மொத்தம் {s}?","scene.probability.heads.objective":"{n} நாணயங்களைச் சுண்டுகிறீர்கள். எத்தனை விளைவுகளில் சரியாக {k} தலைகள்?","scene.probability.at_least_one_six.objective":"{n} பகடைகளை உருட்டுகிறீர்கள். எத்தனை விளைவுகளில் குறைந்தது ஒரு ஆறு?","hint.probability.1":"வழிகளுக்கு ஒரு சிறிய அட்டவணை போடுங்கள், அல்லது எண்ணுங்கள்.","hint.probability.2":"சரியாக k தலைகள்: எந்த k நாணயங்கள் தலை என்று தேர்ந்தெடுங்கள், C(n, k).","hint.probability.3":"குறைந்தது ஒன்று: எல்லா விளைவுகளையும் எண்ணி, ஒன்றும் இல்லாதவற்றைக் கழியுங்கள்.","concept.probability.name":"விளைவுகளை எண்ணுதல்","concept.probability.idea":"நிகழ்தகவு என்பது சாதகமான விளைவுகள் வகுத்தல் அனைத்து விளைவுகள், எனவே கவனமாக எண்ணுங்கள்.","concept.probability.seen":"சீரற்ற அல்காரிதங்கள், சோதனை, சுமை மதிப்பீடுகள், ஹேஷ் மோதல்கள்","reveal.probability":"கணக்கில் வர வேண்டிய ஒவ்வொரு விளைவையும் எண்ணினீர்கள்.","place.caching.name":"கேஷிங்","place.caching.tagline":"எதை வைப்பது, எதை விடுவது","scene.caching.lru.objective":"கேஷில் {cap} பொருட்கள் இருக்கும், மிக நீண்ட நாளாகப் பயன்படுத்தாதது வெளியேறும். எத்தனை கோரிக்கைகள் தவறுகின்றன?","scene.caching.fifo.objective":"கேஷில் {cap} பொருட்கள் இருக்கும், முதலில் சேர்க்கப்பட்டது வெளியேறும். எத்தனை கோரிக்கைகள் தவறுகின்றன?","hint.caching.1":"தவறல் என்பது கேஷில் இல்லாத ஒன்றுக்கான கோரிக்கை. பிறகு அது சேர்க்கப்படும்.","hint.caching.2":"கேஷ் நிரம்பியிருந்தால் முதலில் ஒன்று வெளியேற வேண்டும்.","hint.caching.3":"LRU: வெற்றி ஒரு பொருளை மீண்டும் புதிதாக்கும். FIFO: வெற்றிகள் எதையும் மாற்றாது.","concept.caching.name":"கேஷிங்","concept.caching.idea":"கேஷ் சமீபத்திய பொருட்களை அருகில் வைக்கும். வெளியேற்றும் விதி எத்தனை முறை தவறும் என்பதைத் தீர்மானிக்கும்.","concept.caching.seen":"CPU கேஷ்கள், உலாவி கேஷ்கள், CDN-கள், தரவுத்தள பஃபர்கள்","reveal.caching":"கேஷில் சரியானவற்றை வைத்தீர்கள்.","place.rate_limiting.name":"சுமையும் வரம்புகளும்","place.rate_limiting.tagline":"வீத வரம்பு மற்றும் சுமை சமன்படுத்தல்","scene.rate_limiting.token_bucket.objective":"வாளியில் {cap} டோக்கன்கள் பிடிக்கும், நிரம்பித் தொடங்கி ஒவ்வொரு விநாடியும் {rate} பெறும். ஒவ்வொரு கோரிக்கையும் ஒன்றைப் பயன்படுத்தும். ஒவ்வொரு விநாடிக்கான கோரிக்கைகள் காட்டப்பட்டுள்ளன. எத்தனை கடந்து செல்லும்?","scene.rate_limiting.round_robin.objective":"{m} சர்வர்கள் முறைப்படி கோரிக்கைகளை ஏற்கின்றன, சர்வர் 1-இலிருந்து தொடங்கி. கோரிக்கை {n} எந்த சர்வருக்குச் செல்லும்?","scene.rate_limiting.least_loaded.objective":"ஒவ்வொரு பணியும் {servers} சர்வர்களில் இதுவரை குறைந்த வேலை உள்ளதுக்குச் செல்லும். மிகவும் பரபரப்பான சர்வருக்கு இறுதியில் எவ்வளவு வேலை?","hint.rate_limiting.1":"ஒரு விநாடி, அல்லது ஒரு பணி வீதம் இயக்கிப் பாருங்கள்.","hint.rate_limiting.2":"ரவுண்ட் ராபின் ஒரு மீதி: சுழற்சியின் எந்த முறை என்று கணக்கிடுங்கள்.","hint.rate_limiting.3":"டோக்கன் வாளி: மீதமுள்ள டோக்கன்களைவிட அதிகமான கோரிக்கைகள் மறுக்கப்படும், வாளி அதன் அளவுக்கு மேல் நிரம்பாது.","concept.rate_limiting.name":"வீத வரம்பு மற்றும் சுமை சமன்படுத்தல்","concept.rate_limiting.idea":"டோக்கன் வாளிகள் திடீர் நெரிசலைச் சமாளிக்கும்; ரவுண்ட் ராபினும் குறைந்த சுமையும் வேலையை சர்வர்களுக்குப் பகிரும்.","concept.rate_limiting.seen":"API நுழைவாயில்கள், வலை சர்வர்கள், வரிசைகள், கிளவுட் தானியங்கி அளவீடு","reveal.rate_limiting":"போக்குவரத்து நியாயமாகப் பகிரப்பட்டது.","tier.easy":"எளிது","tier.medium":"நடுத்தரம்","tier.hard":"கடினம்","action.answer":"சரிபார்","action.probe":"சரிபார்","action.pick":"சரிபார்","action.ops":"சரிபார்","action.route":"சரிபார்","tip.answer":"ஒரு கட்டத்தைத் தட்டி, பிறகு விடையை உள்ளிடுங்கள்.","tip.probe":"கோட்டின் மேல் இழுங்கள் அல்லது − மற்றும் + அழுத்துங்கள், பிறகு சரிபாருங்கள்.","tip.pick":"ஓடுகளைத் தேர்ந்தெடுக்க அவற்றைத் தட்டுங்கள்.","tip.ops":"உங்கள் நகர்வுகளைச் செய்து, பிறகு சரிபாருங்கள்.","tip.route":"ஆரஞ்சுப் புள்ளியிலிருந்து வளையம் வரை இழுங்கள்.","ok.answer":"சரி.","ok.probe":"உறுதியானது.","ok.pick":"இது வேலை செய்கிறது.","ok.ops":"இது வேலை செய்கிறது.","ok.route":"இதைவிடச் சிறந்த பாதை இல்லை.","fail.answer.empty":"முதலில் ஒவ்வொரு விடையையும் நிரப்புங்கள்.","fail.answer.wrong":"முழுமையாகச் சரியில்லை.","fail.answer.some_wrong":"சில விடைகள் தவறு.","fail.probe.out_of_checks":"சோதனைகள் முடிந்தன, ஆனால் ஒன்றுக்கு மேற்பட்ட எண்கள் மீதம்.","fail.pick.empty":"முதலில் சில ஓடுகளைத் தேர்ந்தெடுங்கள்.","fail.pick.wrong_count":"ஓடுகளின் எண்ணிக்கை சரியில்லை.","fail.pick.too_much":"கூட்டுத்தொகை அதிகம்.","fail.pick.too_little":"கூட்டுத்தொகை குறைவு.","fail.pick.wrong_xor":"இந்த ஓடுகளின் XOR வேறு எண்.","fail.pick.not_together":"சாளரத்தின் ஓடுகள் அடுத்தடுத்து இருக்க வேண்டும்.","fail.pick.not_best":"இது வேலை செய்கிறது, ஆனால் இதைவிடச் சிறந்த தேர்வு உள்ளது.","fail.pick.overlap":"இவற்றில் இரண்டு மேற்பொருந்துகின்றன.","fail.pick.over_cap":"பைக்கு மிகவும் கனம்.","fail.ops.wrong_order":"ஏதோ ஒன்று தவறான வரிசையில் வெளியேறியது.","fail.ops.unfinished":"இன்னும் முடியவில்லை.","fail.ops.unsorted":"இன்னும் வரிசையில் இல்லை.","fail.ops.too_many_moves":"அடுக்கப்பட்டது, ஆனால் தேவையைவிட அதிக இடமாற்றங்களில்.","fail.ops.too_early":"ஒரு பணி தனக்குத் தேவையான ஒன்றுக்கு முன் வந்துவிட்டது.","fail.route.unfinished":"பாதை வளையத்தை அடைய வேண்டும்.","fail.route.longer":"இது அடைகிறது, ஆனால் இதைவிடச் சிறந்த பாதை உள்ளது.","probe.higher":"பெரியது","probe.lower":"சிறியது","probe.good":"சரி","probe.bad":"மோசம்","probe.found":"கிடைத்தது","probe.start":"சோதிக்க ஒரு எண்ணைத் தேர்ந்தெடுங்கள்.","probe.left":"இன்னும் {left} சாத்தியம்.","probe.bisect_note":"மோசம் என்றால் முதல் மோசமானது இங்கே அல்லது முன்னால்.","ops.push":"Push","ops.pop":"Pop","ops.target":"இலக்கு","ops.in":"உள்ளே","ops.out":"வெளியே","route.steps":"படிகள்","route.cost":"செலவு","field.front":"முன்","field.size":"அளவு","field.last_out":"கடைசியாக வெளியேறியது","field.first_out":"முதலில் வெளியேறியது","field.top":"மேல்","field.groups":"குழுக்கள்","field.biggest":"பெரியது","ui.locked_tier":"இந்தத் தலைப்பைத் திறக்க இன்னும் {count} {tier} காட்சிகளைத் தீர்த்துவிடுங்கள்."}
